const svg=$('#nf-svg'), out=$('#nf-out');
const sl={cc:$('#nf-cc-r'),cd:$('#nf-cd-r'),dc:$('#nf-dc-r'),dd:$('#nf-dd-r')};
const lb={cc:$('#nf-cc-r-lbl'),cd:$('#nf-cd-r-lbl'),dc:$('#nf-dc-r-lbl'),dd:$('#nf-dd-r-lbl')};
const resetBtn=$('#nf-reset');
// symmetric game: column payoffs are the transpose of row payoffs.
// row strategies 0=Cooperate,1=Defect ; col strategies 0=Cooperate,1=Defect
function payoffs(){
  const R=[[+sl.cc.value,+sl.cd.value],[+sl.dc.value,+sl.dd.value]];
  // symmetric: column player's payoff at (rowStrat i, colStrat j) = R[j][i]
  const C=[[R[0][0],R[1][0]],[R[0][1],R[1][1]]];
  return {R,C};
}
function rowDom(R){ // returns [winner,loser] if a row strictly dominates the other
  for(const [i,k] of [[0,1],[1,0]]) if([0,1].every(j=>R[i][j] > R[k][j])) return [i,k];
  return null;
}
function colDom(C){
  for(const [j,l] of [[0,1],[1,0]]) if([0,1].every(i=>C[i][j] > C[i][l])) return [j,l];
  return null;
}
const names=['C (cooperate)','D (defect)'];
function render(){
  for(const k in sl) lb[k].textContent=sl[k].value;
  const {R,C}=payoffs();
  const rd=rowDom(R), cd=colDom(C);
  svg.innerHTML='';
  const x0=170,y0=70,cw=190,ch=95; // grid origin and cell size
  // shade dominated row / column
  if(rd){ const loser=rd[1]; svg.appendChild(SVG('rect',{x:x0,y:y0+loser*ch,width:cw*2,height:ch,fill:'var(--pink)',opacity:0.16})); }
  if(cd){ const loser=cd[1]; svg.appendChild(SVG('rect',{x:x0+loser*cw,y:y0,width:cw,height:ch*2,fill:'var(--cyan)',opacity:0.14})); }
  // grid lines
  for(let r=0;r<=2;r++) svg.appendChild(SVG('line',{x1:x0,y1:y0+r*ch,x2:x0+2*cw,y2:y0+r*ch,stroke:'var(--line)','stroke-width':1.2}));
  for(let c=0;c<=2;c++) svg.appendChild(SVG('line',{x1:x0+c*cw,y1:y0,x2:x0+c*cw,y2:y0+2*ch,stroke:'var(--line)','stroke-width':1.2}));
  // headers
  const colHdr=SVG('text',{x:x0+cw,y:y0-32,'text-anchor':'middle','font-size':13,fill:'var(--mute)'}); colHdr.textContent='Column player'; svg.appendChild(colHdr);
  const rowHdr=SVG('text',{x:x0-118,y:y0+ch,'text-anchor':'middle','font-size':13,fill:'var(--mute)','transform':'rotate(-90 '+(x0-118)+' '+(y0+ch)+')'}); rowHdr.textContent='Row player'; svg.appendChild(rowHdr);
  for(let j=0;j<2;j++){ const t=SVG('text',{x:x0+cw*j+cw/2,y:y0-10,'text-anchor':'middle','font-size':12,fill:'var(--violet)','font-weight':600}); t.textContent=names[j]; svg.appendChild(t); }
  for(let i=0;i<2;i++){ const t=SVG('text',{x:x0-12,y:y0+ch*i+ch/2,'text-anchor':'end','font-size':12,fill:'var(--violet)','font-weight':600}); t.textContent=names[i]; svg.appendChild(t); }
  // cell entries (Row, Col)
  for(let i=0;i<2;i++) for(let j=0;j<2;j++){
    const cx=x0+cw*j+cw/2, cy=y0+ch*i+ch/2;
    const tr=SVG('text',{x:cx,y:cy-4,'text-anchor':'middle','font-size':18,fill:'var(--yellow)','font-weight':700}); tr.textContent='('+R[i][j]+', '+C[i][j]+')'; svg.appendChild(tr);
    const sub=SVG('text',{x:cx,y:cy+18,'text-anchor':'middle','font-size':10,fill:'var(--mute)'}); sub.textContent='row, col'; svg.appendChild(sub);
  }
  let msg='';
  if(rd) msg += 'Row: '+names[rd[0]]+' strictly dominates '+names[rd[1]]+' (shaded).\n';
  else msg += 'Row: no strictly dominated strategy.\n';
  if(cd) msg += 'Column: '+names[cd[0]]+' strictly dominates '+names[cd[1]]+' (shaded).';
  else msg += 'Column: no strictly dominated strategy.';
  if(rd&&cd&&rd[0]===1&&cd[0]===1) msg += '\nDominance picks out ('+names[1].split(' ')[0]+','+names[1].split(' ')[0]+') — the unique equilibrium.';
  out.textContent=msg;
}
for(const k in sl) sl[k].addEventListener('input',render);
resetBtn.addEventListener('click',()=>{ sl.cc.value=3; sl.cd.value=0; sl.dc.value=5; sl.dd.value=1; render(); });
render();

const svg=$('#nash-svg'), out=$('#nash-out'), pick=$('#nash-pick');
const W=600,H=330;
// each game: R[i][j], C[i][j] for row strat i, col strat j ; labels for the two strategies
const GAMES={
  coord:{name:'coordination',rows:['A','B'],cols:['A','B'],R:[[2,0],[0,1]],C:[[2,0],[0,1]]},
  pd:{name:"Prisoner's Dilemma",rows:['C','D'],cols:['C','D'],R:[[3,0],[5,1]],C:[[3,5],[0,1]]},
  mp:{name:'matching pennies',rows:['H','T'],cols:['H','T'],R:[[1,-1],[-1,1]],C:[[-1,1],[1,-1]]},
  bos:{name:'battle of the sexes',rows:['O','F'],cols:['O','F'],R:[[2,0],[0,1]],C:[[1,0],[0,2]]}
};
let cur='coord';
function pureNE(R,C){ const res=[]; for(let i=0;i<2;i++) for(let j=0;j<2;j++){ if(R[i][j] >= R[1-i][j] && C[i][j] >= C[i][1-j]) res.push([i,j]); } return res; }
function bestRow(R,j){ return R[0][j] >= R[1][j] ? [0] : [1]; } // index of row best response to col j (ties->both handled below)
function rowBR(R,j){ const a=R[0][j],b=R[1][j]; if(a>b) return [0]; if(b>a) return [1]; return [0,1]; }
function colBR(C,i){ const a=C[i][0],b=C[i][1]; if(a>b) return [0]; if(b>a) return [1]; return [0,1]; }
function mixedNE(R,C){
  // p = prob row plays strat0 making COL indifferent
  const Adenom=(C[0][0]-C[0][1])-(C[1][0]-C[1][1]);
  const Bnum=(C[1][0]-C[1][1]);
  const p = Adenom!==0 ? -Bnum/Adenom : null;
  // q = prob col plays strat0 making ROW indifferent
  const A2=(R[0][0]-R[1][0])-(R[0][1]-R[1][1]);
  const B2=(R[0][1]-R[1][1]);
  const q = A2!==0 ? -B2/A2 : null;
  const ok = p!==null && q!==null && p>1e-9 && p<1-1e-9 && q>1e-9 && q<1-1e-9;
  return {p,q,ok};
}
function render(){
  const G=GAMES[cur]; const {R,C}=G; svg.innerHTML='';
  const pures=pureNE(R,C);
  const x0=180,y0=80,cw=180,ch=95;
  // highlight pure NE cells
  for(const [i,j] of pures) svg.appendChild(SVG('rect',{x:x0+j*cw,y:y0+i*ch,width:cw,height:ch,fill:'var(--green)',opacity:0.18}));
  for(let r=0;r<=2;r++) svg.appendChild(SVG('line',{x1:x0,y1:y0+r*ch,x2:x0+2*cw,y2:y0+r*ch,stroke:'var(--line)','stroke-width':1.2}));
  for(let c=0;c<=2;c++) svg.appendChild(SVG('line',{x1:x0+c*cw,y1:y0,x2:x0+c*cw,y2:y0+2*ch,stroke:'var(--line)','stroke-width':1.2}));
  const colHdr=SVG('text',{x:x0+cw,y:y0-30,'text-anchor':'middle','font-size':13,fill:'var(--mute)'}); colHdr.textContent='Column'; svg.appendChild(colHdr);
  const rowHdr=SVG('text',{x:x0-100,y:y0+ch,'text-anchor':'middle','font-size':13,fill:'var(--mute)','transform':'rotate(-90 '+(x0-100)+' '+(y0+ch)+')'}); rowHdr.textContent='Row'; svg.appendChild(rowHdr);
  for(let j=0;j<2;j++){ const t=SVG('text',{x:x0+cw*j+cw/2,y:y0-10,'text-anchor':'middle','font-size':13,fill:'var(--violet)','font-weight':600}); t.textContent=G.cols[j]; svg.appendChild(t); }
  for(let i=0;i<2;i++){ const t=SVG('text',{x:x0-12,y:y0+ch*i+ch/2,'text-anchor':'end','font-size':13,fill:'var(--violet)','font-weight':600}); t.textContent=G.rows[i]; svg.appendChild(t); }
  // mark best responses: underline Row payoff if row best-responds (per column); ring Col payoff if col best-responds (per row)
  for(let i=0;i<2;i++) for(let j=0;j<2;j++){
    const cx=x0+cw*j+cw/2, cy=y0+ch*i+ch/2;
    const rBR = rowBR(R,j).includes(i);
    const cBR = colBR(C,i).includes(j);
    const tr=SVG('text',{x:cx,y:cy+5,'text-anchor':'middle','font-size':17,'font-weight':700}); tr.textContent='('+R[i][j]+', '+C[i][j]+')';
    tr.setAttribute('fill', (rBR&&cBR)?'var(--green)':'var(--yellow)'); svg.appendChild(tr);
    let tag='';
    if(rBR) tag+='R★'; if(cBR) tag+=(tag?'  ':'')+'C★';
    if(tag){ const tg=SVG('text',{x:cx,y:cy+24,'text-anchor':'middle','font-size':10,fill:'var(--mute)'}); tg.textContent=tag+' best response'; svg.appendChild(tg); }
  }
  const mix=mixedNE(R,C);
  let msg=G.name+'\n';
  if(pures.length) msg += 'pure Nash equilibria: '+pures.map(([i,j])=>'('+G.rows[i]+','+G.cols[j]+')').join(', ')+'\n';
  else msg += 'pure Nash equilibria: none\n';
  if(mix.ok) msg += 'mixed NE: Row plays '+G.rows[0]+' w.p. '+mix.p.toFixed(3)+', Col plays '+G.cols[0]+' w.p. '+mix.q.toFixed(3)+'   (indifference)';
  else msg += 'no interior (fully mixed) NE — equilibrium play is pure';
  out.textContent=msg;
}
pick.addEventListener('change',()=>{ cur=pick.value; render(); });
render();

const svg=$('#mm-svg'), out=$('#mm-out');
const sl={a11:$('#mm-a11'),a12:$('#mm-a12'),a21:$('#mm-a21'),a22:$('#mm-a22')};
const lb={a11:$('#mm-a11-lbl'),a12:$('#mm-a12-lbl'),a21:$('#mm-a21-lbl'),a22:$('#mm-a22-lbl')};
const resetBtn=$('#mm-reset');
function solve(A){
  const rowMins=[Math.min(A[0][0],A[0][1]),Math.min(A[1][0],A[1][1])];
  const maximin=Math.max(rowMins[0],rowMins[1]);
  const colMaxs=[Math.max(A[0][0],A[1][0]),Math.max(A[0][1],A[1][1])];
  const minimax=Math.min(colMaxs[0],colMaxs[1]);
  if(maximin===minimax){
    // pure saddle: find a cell that is a row-max within its column and a col-min within its row
    for(let i=0;i<2;i++) for(let j=0;j<2;j++){ if(A[i][j]===Math.max(A[0][j],A[1][j]) && A[i][j]===Math.min(A[i][0],A[i][1])) return {pure:true,value:A[i][j],i,j}; }
    return {pure:true,value:maximin};
  }
  const den=A[0][0]+A[1][1]-A[0][1]-A[1][0];
  const p=(A[1][1]-A[1][0])/den;          // prob row plays row 1
  const q=(A[1][1]-A[0][1])/den;          // prob col plays col 1
  const v=(A[0][0]*A[1][1]-A[0][1]*A[1][0])/den;
  return {pure:false,value:v,p,q};
}
function render(){
  for(const k in sl) lb[k].textContent=sl[k].value;
  const A=[[+sl.a11.value,+sl.a12.value],[+sl.a21.value,+sl.a22.value]];
  const S=solve(A); svg.innerHTML='';
  const x0=160,y0=80,cw=150,ch=90;
  if(S.pure && S.i!=null) svg.appendChild(SVG('rect',{x:x0+S.j*cw,y:y0+S.i*ch,width:cw,height:ch,fill:'var(--green)',opacity:0.2}));
  for(let r=0;r<=2;r++) svg.appendChild(SVG('line',{x1:x0,y1:y0+r*ch,x2:x0+2*cw,y2:y0+r*ch,stroke:'var(--line)','stroke-width':1.2}));
  for(let c=0;c<=2;c++) svg.appendChild(SVG('line',{x1:x0+c*cw,y1:y0,x2:x0+c*cw,y2:y0+2*ch,stroke:'var(--line)','stroke-width':1.2}));
  const ch1=SVG('text',{x:x0+cw,y:y0-30,'text-anchor':'middle','font-size':13,fill:'var(--mute)'}); ch1.textContent='Column (minimizer)'; svg.appendChild(ch1);
  const rh=SVG('text',{x:x0-90,y:y0+ch,'text-anchor':'middle','font-size':13,fill:'var(--mute)','transform':'rotate(-90 '+(x0-90)+' '+(y0+ch)+')'}); rh.textContent='Row (maximizer)'; svg.appendChild(rh);
  for(let i=0;i<2;i++) for(let j=0;j<2;j++){ const cx=x0+cw*j+cw/2, cy=y0+ch*i+ch/2; const t=SVG('text',{x:cx,y:cy+6,'text-anchor':'middle','font-size':20,fill:'var(--yellow)','font-weight':700}); t.textContent=A[i][j]; svg.appendChild(t); }
  // strategy weight bars (right side) when mixed
  let msg='';
  if(S.pure){
    msg='PURE SADDLE POINT: max-min = min-max = '+S.value+'\nvalue v = '+S.value+'    (a pure-strategy Nash equilibrium; no mixing needed)';
  } else {
    const p=S.p,q=S.q;
    msg='no pure saddle (max-min < min-max), so the players mix:\n'+
        'Row optimal x* = ('+p.toFixed(3)+', '+(1-p).toFixed(3)+')   [PRIMAL LP solution]\n'+
        'Col optimal y* = ('+q.toFixed(3)+', '+(1-q).toFixed(3)+')   [DUAL LP solution]\n'+
        'value  v = max_x min_y xᵀAy = min_y max_x xᵀAy = '+S.value.toFixed(3)+'\n'+
        'primal optimum = dual optimum = v  (LP strong duality = minimax)';
  }
  out.textContent=msg;
}
for(const k in sl) sl[k].addEventListener('input',render);
resetBtn.addEventListener('click',()=>{ sl.a11.value=1; sl.a12.value=-1; sl.a21.value=-1; sl.a22.value=1; render(); });
render();

const svg=$('#mx-svg'), out=$('#mx-out'), gameSel=$('#mx-game');
const pSl=$('#mx-p'), pL=$('#mx-p-lbl');
const W=600,H=340;
// Row payoff matrix R[i][j]: i = Row action (0/1), j = Col action (0/1).
// Row's EU to action i, given Col plays action0 w.p. p: p*R[i][0] + (1-p)*R[i][1]
const GAMES={
  mp:{name:'matching pennies',acts:['Heads','Tails'],R:[[1,-1],[-1,1]]},
  bos:{name:'battle of the sexes (Row)',acts:['Opera','Football'],R:[[2,0],[0,1]]}
};
let cur='mp';
function euRow(R,i,p){ return p*R[i][0] + (1-p)*R[i][1]; }
function crossing(R){ // p where euRow(0)=euRow(1)
  const A=(R[0][0]-R[0][1])-(R[1][0]-R[1][1]);
  const B=(R[0][1]-R[1][1]);
  return A!==0 ? -B/A : null;
}
function render(){
  const G=GAMES[cur], R=G.R; const p=+pSl.value; pL.textContent='p = '+p.toFixed(2);
  svg.innerHTML='';
  const padL=70,padR=40,padT=40,padB=50;
  const pw=W-padL-padR, phh=H-padT-padB;
  // y-range over all payoffs
  const vals=[R[0][0],R[0][1],R[1][0],R[1][1]];
  let ymin=Math.min(...vals), ymax=Math.max(...vals); if(ymin===ymax){ymin-=1;ymax+=1;} const pad=(ymax-ymin)*0.15; ymin-=pad; ymax+=pad;
  const X=pp=>padL+pp*pw;
  const Y=v=>padT+(ymax-v)/(ymax-ymin)*phh;
  // axes
  svg.appendChild(SVG('line',{x1:padL,y1:padT,x2:padL,y2:padT+phh,stroke:'var(--line)','stroke-width':1.5}));
  svg.appendChild(SVG('line',{x1:padL,y1:Y(0),x2:padL+pw,y2:Y(0),stroke:'var(--line)','stroke-width':1}));
  // x ticks at p=0,0.5,1
  for(const tp of [0,0.5,1]){ svg.appendChild(SVG('line',{x1:X(tp),y1:padT+phh,x2:X(tp),y2:padT+phh+5,stroke:'var(--mute)'})); const t=SVG('text',{x:X(tp),y:padT+phh+20,'text-anchor':'middle','font-size':11,fill:'var(--mute)'}); t.textContent='p='+tp; svg.appendChild(t); }
  const xlab=SVG('text',{x:padL+pw/2,y:H-8,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); xlab.textContent="Column's probability p on action 1"; svg.appendChild(xlab);
  const ylab=SVG('text',{x:18,y:padT+phh/2,'text-anchor':'middle','font-size':12,fill:'var(--mute)','transform':'rotate(-90 18 '+(padT+phh/2)+')'}); ylab.textContent="Row's expected payoff"; svg.appendChild(ylab);
  // two payoff lines
  const cols=['var(--cyan)','var(--pink)'];
  for(let i=0;i<2;i++){ const y0=euRow(R,i,0), y1=euRow(R,i,1); svg.appendChild(SVG('line',{x1:X(0),y1:Y(y1),x2:X(1),y2:Y(y0),stroke:cols[i],'stroke-width':2.5})); const t=SVG('text',{x:X(1)-4,y:Y(y0)-6,'text-anchor':'end','font-size':12,fill:cols[i],'font-weight':600}); t.textContent='play '+G.acts[i]; svg.appendChild(t); }
  // crossing
  const pc=crossing(R);
  if(pc!==null && pc>=0 && pc<=1){ const yc=euRow(R,0,pc); svg.appendChild(SVG('line',{x1:X(pc),y1:padT,x2:X(pc),y2:padT+phh,stroke:'var(--yellow)','stroke-dasharray':'4 3','stroke-width':1.5})); svg.appendChild(SVG('circle',{cx:X(pc),cy:Y(yc),r:6,fill:'var(--yellow)',stroke:'#111','stroke-width':1.5})); const t=SVG('text',{x:X(pc),y:padT-8,'text-anchor':'middle','font-size':12,fill:'var(--yellow)','font-weight':700}); t.textContent='indifference  p* = '+pc.toFixed(3); svg.appendChild(t); }
  // moving marker at current p on both lines
  for(let i=0;i<2;i++){ svg.appendChild(SVG('circle',{cx:X(p),cy:Y(euRow(R,i,p)),r:4,fill:cols[i]})); }
  svg.appendChild(SVG('line',{x1:X(p),y1:padT,x2:X(p),y2:padT+phh,stroke:'var(--mute)','stroke-dasharray':'2 4','stroke-width':1}));
  let msg=G.name+'\n'+
    "at p = "+p.toFixed(2)+":  Row's EU("+G.acts[0]+") = "+euRow(R,0,p).toFixed(3)+",  EU("+G.acts[1]+") = "+euRow(R,1,p).toFixed(3)+'\n';
  if(pc!==null && pc>=0 && pc<=1) msg += 'indifference at p* = '+pc.toFixed(3)+': Row is indifferent, so this is Column\u2019s equilibrium mix.';
  else msg += 'no interior indifference point — Row strictly prefers one action for all p (a pure best response).';
  out.textContent=msg;
}
gameSel.addEventListener('change',()=>{ cur=gameSel.value; render(); });
pSl.addEventListener('input',render);
render();

const svg=$('#co-svg'), out=$('#co-out'), gameSel=$('#co-game');
const W=600,H=340;
// characteristic functions on bitmask of {player0,player1,player2}
const V={
  glove:(m)=>{ const left=(m&1)+((m>>1)&1); const right=(m>>2)&1; return Math.min(left,right); },
  essential:(m)=>{ const has0=(m&1)!==0; const size=(m&1)+((m>>1)&1)+((m>>2)&1); if(size===3) return 1; return (has0&&size>=2)?1:0; },
  majority:(m)=>{ const size=(m&1)+((m>>1)&1)+((m>>2)&1); return size>=2?1:0; }
};
const NAMES={glove:'glove market',essential:'essential player 1',majority:'3-player majority'};
let cur='glove';
function perms(arr){ if(arr.length<=1) return [arr]; let res=[]; for(let i=0;i<arr.length;i++){ const rest=arr.slice(0,i).concat(arr.slice(i+1)); for(const p of perms(rest)) res.push([arr[i],...p]); } return res; }
function shapley(v){ const orders=perms([0,1,2]); const phi=[0,0,0]; const detail=[]; for(const o of orders){ let mask=0; const row=[]; for(const i of o){ const before=v(mask); const after=v(mask|(1<<i)); phi[i]+=after-before; row.push({i,marg:after-before}); mask|=(1<<i); } detail.push({order:o,row}); } return {phi:phi.map(x=>x/orders.length),detail}; }
function render(){
  const v=V[cur]; const {phi,detail}=shapley(v); svg.innerHTML='';
  // bar chart of phi_i
  const padL=70,padB=60,padT=50; const bw=90, gap=60; const baseY=H-padB; const maxPhi=Math.max(1, ...phi);
  const scale=(H-padT-padB)/maxPhi;
  const cols=['var(--cyan)','var(--violet)','var(--green)'];
  svg.appendChild(SVG('line',{x1:padL-10,y1:baseY,x2:W-30,y2:baseY,stroke:'var(--line)','stroke-width':1.5}));
  for(let i=0;i<3;i++){ const x=padL+i*(bw+gap); const h=phi[i]*scale; svg.appendChild(SVG('rect',{x,y:baseY-h,width:bw,height:Math.max(h,1),rx:5,fill:cols[i],opacity:0.85,stroke:'var(--line)'})); const val=SVG('text',{x:x+bw/2,y:baseY-h-8,'text-anchor':'middle','font-size':14,fill:cols[i],'font-weight':700}); val.textContent=phi[i].toFixed(3); svg.appendChild(val); const lab=SVG('text',{x:x+bw/2,y:baseY+22,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); lab.textContent='player '+(i+1); svg.appendChild(lab); }
  const cap=SVG('text',{x:padL-10,y:30,'font-size':12,fill:'var(--mute)'}); cap.textContent=NAMES[cur]+"   \u2014   Shapley value \u03c6 = average marginal contribution over 6 orderings"; svg.appendChild(cap);
  const sum=phi[0]+phi[1]+phi[2];
  // show the 6 orderings with marginal contributions
  let lines=detail.map(d=>{ const seq=d.order.map(i=>i+1).join('\u2192'); const margs=d.row.map(r=>'p'+(r.i+1)+':'+r.marg).join(' '); return '  '+seq+'   ['+margs+']'; }).join('\n');
  out.textContent =
    NAMES[cur]+'\n'+
    'Shapley value \u03c6 = ('+phi.map(x=>x.toFixed(3)).join(', ')+')   sum = '+sum.toFixed(3)+' = v(N)  (efficiency)\n'+
    'orderings (marginal contribution of each player as they join):\n'+lines;
}
gameSel.addEventListener('change',()=>{ cur=gameSel.value; render(); });
