const svg=$('#mech-svg'), out=$('#mech-out');
const sl={v1:$('#mech-v1'),v2:$('#mech-v2'),v3:$('#mech-v3'),shade:$('#mech-shade')};
const lb={v1:$('#mech-v1-lbl'),v2:$('#mech-v2-lbl'),v3:$('#mech-v3-lbl'),shade:$('#mech-shade-lbl')};
const W=600,H=330;
function render(){
  for(const k in sl) lb[k].textContent=sl[k].value;
  const vals=[+sl.v1.value,+sl.v2.value,+sl.v3.value];
  const b1=+sl.shade.value;
  // truthful bids for the comparison; bidder 1 may deviate to b1 in the second-price test
  const bidsTruth=vals.slice();
  const bidsDev=[b1,vals[1],vals[2]];
  svg.innerHTML='';
  // bar chart of valuations
  const padL=80,baseY=210,bw=90,gap=60,maxV=Math.max(1,...vals,b1);
  const scale=140/maxV;
  const cols=['var(--cyan)','var(--violet)','var(--green)'];
  svg.appendChild(SVG('line',{x1:padL-10,y1:baseY,x2:W-30,y2:baseY,stroke:'var(--line)','stroke-width':1.5}));
  for(let i=0;i<3;i++){ const x=padL+i*(bw+gap); const h=vals[i]*scale; svg.appendChild(SVG('rect',{x,y:baseY-h,width:bw,height:Math.max(h,1),rx:5,fill:cols[i],opacity:0.8,stroke:'var(--line)'})); const t=SVG('text',{x:x+bw/2,y:baseY-h-8,'text-anchor':'middle','font-size':13,fill:cols[i],'font-weight':700}); t.textContent='v='+vals[i]; svg.appendChild(t); const lab=SVG('text',{x:x+bw/2,y:baseY+22,'text-anchor':'middle','font-size':12,fill:'var(--mute)'}); lab.textContent='bidder '+(i+1); svg.appendChild(lab); }
  // mark bidder 1's deviating bid as a dashed cap
  if(b1!==vals[0]){ const x=padL; const hb=b1*scale; svg.appendChild(SVG('line',{x1:x-4,y1:baseY-hb,x2:x+bw+4,y2:baseY-hb,stroke:'var(--yellow)','stroke-dasharray':'4 3','stroke-width':2})); const t=SVG('text',{x:x+bw/2,y:baseY-hb-6,'text-anchor':'middle','font-size':11,fill:'var(--yellow)'}); t.textContent='bid '+b1; svg.appendChild(t); }
  // outcomes
  function auction(bids,price){ // price: 'first' or 'second'
    let order=bids.map((b,i)=>({b,i})).sort((a,c)=>c.b-a.b);
    const winner=order[0].i; const pay = price==='first' ? order[0].b : order[1].b;
    return {winner,pay};
  }
  const fp=auction(bidsTruth,'first');
  const sp=auction(bidsTruth,'second');
  const spDev=auction(bidsDev,'second');
  const truthWinner=sp.winner;
  const surplusTruth = truthWinner===0 ? vals[0]-sp.pay : 0;
  // surplus to bidder 1 under deviation
  const dev1Wins = spDev.winner===0;
  const surplusDev = dev1Wins ? vals[0]-spDev.pay : 0;
  let msg='';
  msg += 'truthful bids = valuations ('+vals.join(', ')+')\n';
  msg += 'FIRST-PRICE (truthful):  bidder '+(fp.winner+1)+' wins, pays '+fp.pay+' = own bid  \u2192 surplus '+(vals[fp.winner]-fp.pay)+'  (so first-price bidders shade DOWN)\n';
  msg += 'SECOND-PRICE (truthful): bidder '+(sp.winner+1)+' wins, pays '+sp.pay+' = runner-up bid  \u2192 surplus '+(vals[sp.winner]-sp.pay)+'\n';
  msg += '\nTruthfulness test (bidder 1 bids '+b1+' instead of v₁='+vals[0]+', second-price):\n';
  if(b1===vals[0]) msg += '  bidding truthfully \u2192 bidder 1 surplus '+surplusTruth+'. Try shading the bid to see it never helps.';
  else { msg += '  bidder '+(spDev.winner+1)+' now wins; bidder 1 surplus = '+surplusDev+(surplusDev<=surplusTruth?'  \u2264  truthful surplus '+surplusTruth+'  \u2192 deviation does NOT help':'  > truthful?!'); msg += '\n  \u2192 truthful bidding weakly dominates: your bid never sets your price, so honesty is optimal.'; }
  out.textContent=msg;
}
for(const k in sl) sl[k].addEventListener('input',render);
